from typing import List

class Solution:
    def largestEvenSum(self, nums: List[int], k: int) -> int:
        nums.sort(reverse=True)
        top = sum(nums[:k])
        if top % 2 == 0:
            return top

        def repair(out_odd):
            out_p = 1 if out_odd else 0
            out = inn = None
            for i in range(k - 1, -1, -1):
                if nums[i] % 2 == out_p:
                    out = nums[i]
                    break
            for i in range(k, len(nums)):
                if nums[i] % 2 != out_p:
                    inn = nums[i]
                    break
            return top - out + inn if out is not None and inn is not None else -1

        return max(repair(True), repair(False))

