class Solution {
public:
    long long largestEvenSum(vector<int>& nums, int k) {
        sort(nums.rbegin(), nums.rend());
        long long top = 0;
        for (int i = 0; i < k; ++i) top += nums[i];
        if (top % 2 == 0) return top;
        auto repair = [&](bool outOdd) {
            int outP = outOdd ? 1 : 0;
            int out = -1, in = -1;
            for (int i = k - 1; i >= 0 && out < 0; --i)
                if ((nums[i] & 1) == outP) out = i;
            for (int i = k; i < (int)nums.size() && in < 0; ++i)
                if ((nums[i] & 1) != outP) in = i;
            return out >= 0 && in >= 0 ? top - nums[out] + nums[in] : -1LL;
        };
        return max(repair(true), repair(false));
    }
};

