class Solution {
    public long largestEvenSum(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] a = new long[n];
        for (int i = 0; i < n; ++i) a[i] = nums[n - 1 - i];
        long top = 0;
        for (int i = 0; i < k; ++i) top += a[i];
        if (top % 2 == 0) return top;
        long ans = -1;
        for (int p = 0; p < 2; ++p) {
            int out = -1, in = -1;
            for (int i = k - 1; i >= 0 && out < 0; --i)
                if (a[i] % 2 == p) out = i;
            for (int i = k; i < n && in < 0; ++i)
                if (a[i] % 2 != p) in = i;
            if (out >= 0 && in >= 0) ans = Math.max(ans, top - a[out] + a[in]);
        }
        return ans;
    }
}

