from typing import List

class Solution:
    def largestEvenSum(self, nums: List[int], k: int) -> int:
        evens = sorted((x for x in nums if x % 2 == 0), reverse=True)
        odds = sorted((x for x in nums if x % 2 == 1), reverse=True)
        preE, preO = [0], [0]
        for x in evens:
            preE.append(preE[-1] + x)
        for x in odds:
            preO.append(preO[-1] + x)
        ans = -1
        for j in range(0, min(len(odds), k) + 1, 2):
            if k - j <= len(evens):
                ans = max(ans, preO[j] + preE[k - j])
        return ans

