class Solution {
public:
    long long largestEvenSum(vector<int>& nums, int k) {
        vector<long long> evens, odds;
        for (int x : nums) ((x & 1) ? odds : evens).push_back(x);
        sort(evens.rbegin(), evens.rend());
        sort(odds.rbegin(), odds.rend());
        vector<long long> preE{0}, preO{0};
        for (long long x : evens) preE.push_back(preE.back() + x);
        for (long long x : odds) preO.push_back(preO.back() + x);
        long long ans = -1;
        for (int j = 0; j <= (int)odds.size() && j <= k; j += 2)
            if (k - j <= (int)evens.size())
                ans = max(ans, preO[j] + preE[k - j]);
        return ans;
    }
};

