class Solution {
    public long largestEvenSum(int[] nums, int k) {
        List<Long> evens = new ArrayList<>(), odds = new ArrayList<>();
        for (int x : nums) (x % 2 == 0 ? evens : odds).add((long) x);
        evens.sort(Collections.reverseOrder());
        odds.sort(Collections.reverseOrder());
        long[] preE = new long[evens.size() + 1], preO = new long[odds.size() + 1];
        for (int i = 0; i < evens.size(); ++i) preE[i + 1] = preE[i] + evens.get(i);
        for (int i = 0; i < odds.size(); ++i) preO[i + 1] = preO[i] + odds.get(i);
        long ans = -1;
        for (int j = 0; j <= odds.size() && j <= k; j += 2)
            if (k - j <= evens.size())
                ans = Math.max(ans, preO[j] + preE[k - j]);
        return ans;
    }
};

