var largestEvenSum = function(nums, k) {
    const evens = nums.filter(x => x % 2 === 0).sort((a, b) => b - a);
    const odds = nums.filter(x => x % 2 !== 0).sort((a, b) => b - a);
    const preE = [0], preO = [0];
    for (const x of evens) preE.push(preE[preE.length - 1] + x);
    for (const x of odds) preO.push(preO[preO.length - 1] + x);
    let ans = -1;
    for (let j = 0; j <= odds.length && j <= k; j += 2)
        if (k - j <= evens.length)
            ans = Math.max(ans, preO[j] + preE[k - j]);
    return ans;
};
